// src/App.jsx
import React, { useState } from "react";
import { Bar, Pie } from "react-chartjs-2";
import "chart.js/auto";

function App() {
  const [resultados, setResultados] = useState(null);
  const [cargando, setCargando] = useState(false);
  const tasasOrden = ["0", "1", "2", "4", "8", "13"];

  const subirArchivos = async (e) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const formData = new FormData();
    for (let f of files) formData.append("files", f);

    try {
      setCargando(true);
      const res = await fetch("http://localhost:4000/upload", {
        method: "POST",
        body: formData,
      });
      const data = await res.json();
      // Asegurar estructura
      const iva = data?.iva || {};
      const base = data?.base || {};
      // Normalizar: convertir valores NaN/undefined -> 0
      const ivaNorm = {};
      const baseNorm = {};
      tasasOrden.forEach((t) => {
        ivaNorm[t] = Number(iva[t] || 0);
        baseNorm[t] = Number(base[t] || 0);
      });

      setResultados({ iva: ivaNorm, base: baseNorm });
    } catch (err) {
      console.error("Error subiendo archivos:", err);
      alert("Error al procesar los archivos. Revisa la consola.");
    } finally {
      setCargando(false);
    }
  };

  // ---------------- Exportar a Excel ----------------
  const exportToExcel = () => {
    if (!resultados) return;
    const XLSX = require("xlsx");
    const rows = [["Tasa IVA", "Monto Base", "IVA"]];
    tasasOrden.forEach((t) => {
      rows.push([`${t}%`, resultados.base[t], resultados.iva[t]]);
    });
    const wb = XLSX.utils.book_new();
    const ws = XLSX.utils.aoa_to_sheet(rows);
    XLSX.utils.book_append_sheet(wb, ws, "Resumen IVA");
    XLSX.writeFile(wb, "IVA_Resumen.xlsx");
  };

  // ---------------- Exportar a PDF ----------------
  const exportToPDF = () => {
    if (!resultados) return;
    const jsPDF = require("jspdf");
    require("jspdf-autotable");
    const doc = new jsPDF();
    doc.setFontSize(16);
    doc.text("Resumen de IVA", 14, 20);

    const body = tasasOrden.map((t) => [
      `${t}%`,
      resultados.base[t].toFixed(2),
      resultados.iva[t].toFixed(2),
    ]);

    doc.autoTable({
      head: [["Tasa IVA", "Monto Base", "IVA"]],
      body,
      startY: 30,
    });
    doc.save("IVA_Resumen.pdf");
  };

  // ---------------- Datos para gráficos ----------------
  const chartBarData = resultados
    ? {
        labels: tasasOrden.map((t) => `${t}%`),
        datasets: [
          {
            label: "Monto Base",
            data: tasasOrden.map((t) => resultados.base[t]),
            // no set colors (Chart.js picks defaults)
          },
          {
            label: "IVA",
            data: tasasOrden.map((t) => resultados.iva[t]),
          },
        ],
      }
    : null;

  const chartPieData = resultados
    ? {
        labels: tasasOrden.map((t) => `${t}%`),
        datasets: [
          {
            label: "Distribución Monto Base",
            data: tasasOrden.map((t) => resultados.base[t]),
          },
        ],
      }
    : null;

  // ---------------- Totales generales ----------------
  const totalBase = resultados
    ? Object.values(resultados.base).reduce((s, v) => s + v, 0)
    : 0;
  const totalIVA = resultados
    ? Object.values(resultados.iva).reduce((s, v) => s + v, 0)
    : 0;

  return (
    <div style={{ padding: 28, fontFamily: "Arial, sans-serif", maxWidth: 1100, margin: "0 auto" }}>
      <h1 style={{ textAlign: "center" }}>Dashboard IVA — XML v4.4</h1>

      <div style={{ display: "flex", gap: 12, alignItems: "center", justifyContent: "center", marginBottom: 18 }}>
        <label style={fileLabelStyle}>
          Seleccionar XML(s)
          <input type="file" multiple accept=".xml" onChange={subirArchivos} style={{ display: "none" }} />
        </label>

        <button onClick={exportToExcel} disabled={!resultados} style={buttonStyle}>
          Exportar a Excel
        </button>
        <button onClick={exportToPDF} disabled={!resultados} style={{ buttonPdfStyle }}>
          Exportar a PDF
        </button>
      </div>

      {cargando && <p style={{ textAlign: "center" }}>Procesando archivos... ⏳</p>}

      {resultados && (
        <>
          <div style={{ display: "flex", gap: 12, flexWrap: "wrap", justifyContent: "center", marginBottom: 20 }}>
            <div style={bigCardStyle}>
              <h3>Total Monto Base</h3>
              <p style={{ fontSize: 20, fontWeight: "700" }}>{totalBase.toLocaleString(undefined, { minimumFractionDigits: 2 })} ₡</p>
            </div>
            <div style={bigCardStyle}>
              <h3>Total IVA</h3>
              <p style={{ fontSize: 20, fontWeight: "700" }}>{totalIVA.toLocaleString(undefined, { minimumFractionDigits: 2 })} ₡</p>
            </div>
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 12 }}>
            {tasasOrden.map((t) => (
              <div key={t} style={cardStyle}>
                <h3>IVA {t}%</h3>
                <p><strong>Monto Base:</strong> ₡{resultados.base[t].toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
                <p><strong>IVA:</strong> ₡{resultados.iva[t].toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
              </div>
            ))}
          </div>

          <div style={{ marginTop: 28, display: "flex", gap: 24, flexWrap: "wrap", justifyContent: "center" }}>
            <div style={{ width: "48%", minWidth: 320 }}>
              <h3>Montos: Barra</h3>
              <Bar data={chartBarData} />
            </div>

            <div style={{ width: "40%", minWidth: 300 }}>
              <h3>Distribución Monto Base</h3>
              <Pie data={chartPieData} />
            </div>
          </div>
        </>
      )}

      {!resultados && !cargando && <p style={{ textAlign: "center", marginTop: 18 }}>Sube tus XML para ver resultados.</p>}
    </div>
  );
}

const fileLabelStyle = {
  background: "#2196F3",
  color: "#fff",
  padding: "10px 14px",
  borderRadius: 8,
  cursor: "pointer",
  fontWeight: 600,
};

const buttonStyle = {
  background: "#4CAF50",
  color: "#fff",
  padding: "10px 14px",
  borderRadius: 8,
  cursor: "pointer",
  border: "none",
  fontWeight: 600,
};

const buttonPdfStyle = {
  ...buttonStyle,
  background: "#E91E63",
};

const cardStyle = {
  background: "#fff",
  padding: 14,
  borderRadius: 10,
  boxShadow: "0 6px 18px rgba(0,0,0,0.08)",
};

const bigCardStyle = {
  background: "#fff",
  padding: 16,
  borderRadius: 10,
  boxShadow: "0 8px 20px rgba(0,0,0,0.09)",
  minWidth: 220,
  textAlign: "center",
};

export default App;
